import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cells=[(i,j,v) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg]
    rs=sorted(set(i for i,_,_ in cells)); cs=sorted(set(j for _,j,_ in cells))
    minr,maxr=min(rs),max(rs); minc,maxc=min(cs),max(cs)
    ring=g[minr][minc]
    inn={v for i,j,v in cells if v!=ring and v!=bg}
    if len(inn)!=1: raise ValueError(inn)
    inner=inn.pop()
    # outer frame color = inner, frame tightly wraps ring bbox
    ot=minr-1; ob=maxr+1; ol=minc-1; or_=maxc+1
    out=[[g[i][j] for j in range(w)] for i in range(h)]
    for i in range(ot,ob+1):
        for j in range(ol,or_+1):
            if g[i][j]==bg: out[i][j]=inner
    return out
